INSERT INTO channel (name, slug, description, user_id, organization_id, status, created_at, updated_at) SELECT 'Acme API Gateway', 'acme.api.gateway', 'API gateway request/response events, rate limiting, and routing metrics for Acme Corp.', 1, (SELECT id FROM organization WHERE slug = 'acme-corp'), 'ACTIVE', (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') - INTERVAL '60 days', (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') - INTERVAL '1 hour' ON CONFLICT DO NOTHING;
INSERT INTO channel (name, slug, description, user_id, organization_id, status, created_at, updated_at) SELECT 'Acme Payment Service', 'acme.payment.service', 'Payment transaction events, fraud detection alerts, and settlement notifications.', 1, (SELECT id FROM organization WHERE slug = 'acme-corp'), 'ACTIVE', (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') - INTERVAL '60 days', (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') - INTERVAL '45 minutes' ON CONFLICT DO NOTHING;
INSERT INTO channel (name, slug, description, user_id, organization_id, status, created_at, updated_at) SELECT 'Acme User Auth', 'acme.user.auth', 'Authentication and authorization events including logins, token refreshes, and access violations.', 1, (SELECT id FROM organization WHERE slug = 'acme-corp'), 'ACTIVE', (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') - INTERVAL '60 days', (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') - INTERVAL '30 minutes' ON CONFLICT DO NOTHING;
INSERT INTO channel (name, slug, description, user_id, organization_id, status, created_at, updated_at) SELECT 'Acme Background Jobs', 'acme.background.jobs', 'Async job queue events: scheduling, execution, retries, and failures.', 1, (SELECT id FROM organization WHERE slug = 'acme-corp'), 'ACTIVE', (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') - INTERVAL '60 days', (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') - INTERVAL '15 minutes' ON CONFLICT DO NOTHING;
